import 'dart:io';import 'package:flutter/material.dart';import 'package:image_picker/image_picker.dart';import '../../core/app_services.dart';import '../../core/models/plant.dart';import '../../core/navigation/app_router.dart';import '../../core/theme/app_theme.dart';
class ScannerScreen extends StatefulWidget{const ScannerScreen({super.key});@override State<ScannerScreen> createState()=>_ScannerScreenState();}
class _ScannerScreenState extends State<ScannerScreen>{late Future<List<Plant>> plants;String? selectedId;String? imagePath;String? error;bool analyzing=false;final picker=ImagePicker();@override void initState(){super.initState();plants=load();}Future<List<Plant>> load()async{final p=await AppServices.garden.getPlants();if(selectedId==null&&p.isNotEmpty)selectedId=p.first.id;return p;}Plant? selected(List<Plant> p)=>p.where((x)=>x.id==selectedId).firstOrNull;
Future<void> pick(ImageSource source)async{if(analyzing)return;final x=await picker.pickImage(source:source,imageQuality:90,maxWidth:2048,maxHeight:2048);if(x!=null)setState((){imagePath=x.path;error=null;});}
Future<void> analyze()async{if(imagePath==null){setState(()=>error='Choose a photo first.');return;}final p=await plants;final plant=selected(p);if(plant==null){setState(()=>error='Add a plant before scanning.');return;}setState((){analyzing=true;error=null;});try{final u=await AppServices.auth.currentUser();if(u==null)throw StateError('Sign in required.');final ref=await AppServices.imageStorage.uploadPlantImage(filePath:imagePath!,userId:u.id);final result=await AppServices.diagnosis.diagnose(imagePath:imagePath!,imageReference:ref,plantId:plant.id,plantHint:plant.name);if(mounted)Navigator.pushNamed(context,AppRouter.diagnosis,arguments:result);}catch(_){if(mounted)setState(()=>error='We could not analyze this photo. Try a clearer image.');}finally{if(mounted)setState(()=>analyzing=false);}}
