const SizedBox(height:16),const Text('SELECT PLANT',style:TextStyle(fontSize:12,fontWeight:FontWeight.w900,letterSpacing:.7,color:PlantCareColors.primary)),const SizedBox(height:8),
if(p.isEmpty)Card(child:ListTile(leading:const Icon(Icons.eco_outlined,color:PlantCareColors.primary),title:const Text('No plants yet',style:TextStyle(fontWeight:FontWeight.w800)),subtitle:const Text('Add a plant so this scan can be saved to your garden.'),trailing:TextButton(onPressed:()=>Navigator.pushNamed(c,AppRouter.addPlant),child:const Text('ADD'))) else DropdownButtonFormField<String>(initialValue:plant?.id,decoration:const InputDecoration(prefixIcon:Icon(Icons.eco_outlined),hintText:'Choose from My Plants'),items:[for(final x in p)DropdownMenuItem(value:x.id,child:Text(x.name))],onChanged:analyzing?null:(v)=>setState(()=>selectedId=v)),
const SizedBox(height:18),const Text('PHOTO',style:TextStyle(fontSize:12,fontWeight:FontWeight.w900,letterSpacing:.7,color:PlantCareColors.primary)),const SizedBox(height:8),
Container(height:300,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(12),border:Border.all(color:PlantCareColors.border)),child:analyzing?const Center(child:Column(mainAxisSize:MainAxisSize.min,children:[CircularProgressIndicator(),SizedBox(height:14),Text('Analyzing plant…',style:TextStyle(fontWeight:FontWeight.w800)),SizedBox(height:4),Text('Checking visual disease signals',style:TextStyle(color:PlantCareColors.muted,fontSize:12))]):imagePath==null?const Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.document_scanner_outlined,size:48,color:PlantCareColors.primary),SizedBox(height:10),Text('Add a clear plant photo',style:TextStyle(fontSize:17,fontWeight:FontWeight.w800)),SizedBox(height:4),Text('Good light • leaf in focus • affected area visible',style:TextStyle(color:PlantCareColors.muted,fontSize:12))]):Stack(fit:StackFit.expand,children:[ClipRRect(borderRadius:BorderRadius.circular(12),child:Image.file(File(imagePath!),fit:BoxFit.cover)),Positioned(top:8,right:8,child:IconButton.filledTonal(onPressed:()=>setState(()=>imagePath=null),icon:const Icon(Icons.close)))])),
if(error!=null)Padding(padding:const EdgeInsets.only(top:8),child:Text(error!,textAlign:TextAlign.center,style:const TextStyle(color:PlantCareColors.danger))),
const SizedBox(height:12),Row(children:[Expanded(child:OutlinedButton.icon(onPressed:analyzing?null:()=>pick(ImageSource.gallery),icon:const Icon(Icons.photo_library_outlined),label:Text(imagePath==null?'Gallery':'Change'))),const SizedBox(width:8),Expanded(child:FilledButton.icon(onPressed:analyzing?null:()=>pick(ImageSource.camera),icon:const Icon(Icons.camera_alt_outlined),label:Text(imagePath==null?'Camera':'Retake')))]),
if(imagePath!=null&&!analyzing)Padding(padding:const EdgeInsets.only(top:8),child:SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:plant==null?null:analyze,icon:const Icon(Icons.center_focus_strong),label:const Text('ANALYZE PHOTO')))),
const SizedBox(height:8),const Text('PlantCare AI provides an AI-assisted result. Review low-confidence results carefully.',textAlign:TextAlign.center,style:TextStyle(color:PlantCareColors.muted,fontSize:11))]));})),bottomNavigationBar:const AppBottomNav(selectedIndex:2));}
